    A = spdiags([-ones(N-1,1); 0], -1, 2*ones(N,1) - k^2*h^2, 0, [-ones(N-1,1); 0], 1, N) / h^2;

    % Apply boundary conditions
    A(1, :) = 0;
    A(1, 1) = 1;
    A(end, :) = 0;
    A(end, end) = 1;

    % Initialize the Green's function matrix
    G_n = zeros(N, N);

    % Solve for each xi
    for j = 1:N
        b = zeros(N, 1);
        b(j) = 1; % Adjust based on the specific problem
        G_n(:, j) = A \ b;
    end

    % Analytical Green's function
    G_a = @(x, xi) (x <= xi) .* sinh(k*x) * sinh(k*(1 - xi)) / (k * sinh(k)) ...
                 + (x > xi) .* sinh(k*xi) * sinh(k*(1 - x)) / (k * sinh(k));

    % Compute the error
    error = zeros(N, N);
    for i = 1:N
        for j = 1:N
            error(i, j) = abs(G_n(i, j) - G_a(x(i), x(j)));
        end
    end

    % Find the maximum error
    max_error = max(max(error));

    % Display the maximum error
    disp(['Maximum discretization error for k = ', num2str(k), ' and h = ', num2str(h), ': ', num2str(max_error)]);

    % Plot the error
    figure;
    surf(x, x, error);
    title(['Discretization Error Surface for k = ', num2str(k)]);
    xlabel('x');
    ylabel('\xi');
    zlabel('Error');
    colorbar;

    % Plot the numerical Green's function
    figure;
    surf(x, x, G_n);
    title(['Numerical Green''s Function for k = ', num2str(k)]);
    xlabel('x');
    ylabel('\xi');
    zlabel('G_n(x, \xi)');
    colorbar;

    % Plot the analytical Green's function
    figure;
    surf(x, x, arrayfun(G_a, x', x));
    title(['Analytical Green''s Function for k = ', num2str(k)]);
    xlabel('x');
    ylabel('\xi');
    zlabel('G_a(x, \xi)');
    colorbar;
end
