     1.99 & -1 & 0 & \cdots & 0 \\
     -1 & 1.99 & -1 & \cdots & 0 \\
     0 & -1 & 1.99 & \ddots & 0 \\
     \vdots & \vdots & \ddots & \ddots & -1 \\
     0 & 0 & \cdots & -1 & 1.99
