Here is the Mathematica code to perform the necessary calculations and plot the Green's function:

```mathematica
(* Define Airy functions *)
Ai[x_] := AiryAi[-x];
Bi[x_] := AiryBi[-x];
AiPrime[x_] := D[AiryAi[-x], x];
BiPrime[x_] := D[AiryBi[-x], x];

(* Define the coefficients *)
A[xi_] := A[xi];
B[xi_] := B[xi];
C[xi_] := C[xi];
D[xi_] := D[xi];

(* Set up the equations *)
eq1 = A[xi] Ai[0] + B[xi] Bi[0] == 0;
eq2 = C[xi] Ai[-1] + D[xi] Bi[-1] == 0;
eq3 = A[xi] Ai[-xi] + B[xi] Bi[-xi] == C[xi] Ai[-xi] + D[xi] Bi[-xi];
eq4 = C[xi] AiPrime[-xi] + D[xi] BiPrime[-xi] - A[xi] AiPrime[-xi] - B[xi] BiPrime[-xi] == 1;

(* Solve for coefficients *)
sol = Solve[{eq1, eq2, eq3, eq4}, {A[xi], B[xi], C[xi], D[xi]}];

(* Define the Green's function *)
G[x_, xi_] := Piecewise[{
    {A[xi] Ai[x] + B[xi] Bi[x], x < xi},
    {C[xi] Ai[x] + D[xi] Bi[x], x > xi}
}];

(* Substitute the solutions *)
G[x_, xi_] = G[x, xi] /. sol[[1]];

(* Simplify the Green's function *)
G[x_, xi_] = FullSimplify[G[x, xi]];

(* Plot the Green's function for a specific xi *)
Plot[G[x, 0.5], {x, 0, 1}, PlotRange -> All, AxesLabel -> {"x", "G(x, 0.5)"}]
```

