    tau = 0.5;

    for j = 1:length(x)
        for k = 1:length(t)
            G_matrix(j, k) = sum(cellfun(@(n) sin(n*pi*x(j)) * sin(n*pi*xi) * heaviside(t(k)-tau) * exp(-(n*pi)^2 * (t(k)-tau)), num2cell(1:num_terms)));
        end
    end

    % Plot the Green's function
