    xlabel('x');
    ylabel('t');
    zlabel('G(x, \xi, t, \tau)');
    title(['Green''s Function G(x, \xi, t, \tau) for \xi = ', num2str(xi), ' and \tau = ', num2str(tau), ', h = ', num2str(h)]);
    colorbar;
    grid on;
end
```

